#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-03-01

# ============================================================================
# settings.json Validation Test
# ============================================================================
# Validates plugin settings.json structure: that keys CC never reads stay
# absent (#3357), and that the permissions block carries real rules.
# ============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"

TOTAL_PASSED=0
TOTAL_FAILED=0

# Colors
if [[ -t 1 ]]; then
    RED='\033[0;31m' GREEN='\033[0;32m' YELLOW='\033[1;33m'
    BLUE='\033[0;34m' CYAN='\033[0;36m' NC='\033[0m'
else
    RED='' GREEN='' YELLOW='' BLUE='' CYAN='' NC=''
fi

pass() { echo -e "  ${GREEN}PASS${NC} $1"; TOTAL_PASSED=$((TOTAL_PASSED + 1)); }
fail() { echo -e "  ${RED}FAIL${NC} $1"; TOTAL_FAILED=$((TOTAL_FAILED + 1)); }

echo -e "${BLUE}Settings.json Validation${NC}"
echo "========================================"

# Find all settings.json files in plugins/
for settings_file in "$PROJECT_ROOT"/plugins/*/settings.json; do
    [[ -f "$settings_file" ]] || continue
    plugin_name="$(basename "$(dirname "$settings_file")")"
    echo -e "\n${CYAN}Plugin: $plugin_name${NC}"

    # --- Test 1: Valid JSON ---
    if jq empty "$settings_file" 2>/dev/null; then
        pass "Valid JSON"
    else
        fail "Invalid JSON syntax"
        continue
    fi

#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-10

    # --- Test 2: retired keys must not reappear (#3357, #3393) ---
    # Claude Code reads only a narrow set of keys from a PLUGIN settings.json.
    # #3357 removed keybindings/statusLine/spinnerVerbs/spinnerTipsOverride
    # because CC never read any of them.
    #
    # This replaced four presence-guarded blocks that each ended in
    #   pass "<key>: not configured (optional)"
    # Once #3357 removed the keys, all four reported success while asserting
    # nothing, and "optional" implied a supported option that does not exist.
    # Only Test 1 could still fail, so the file validated a schema it no longer
    # had. Keybindings are the sharpest case: CC binds keys to a closed set of
    # built-in namespace:action identifiers, so no plugin can ship a shortcut
    # that invokes a skill at all.
    retired_keys=(keybindings statusLine spinnerVerbs spinnerTipsOverride)
    reappeared=""
    for key in "${retired_keys[@]}"; do
        if [[ "$(jq --arg k "$key" 'has($k)' "$settings_file")" == "true" ]]; then
            reappeared="$reappeared $key"
        fi
    done
    if [[ -z "$reappeared" ]]; then
        pass "Retired keys absent: ${retired_keys[*]}"
    else
        fail "CC never reads these from a plugin settings.json — remove:$reappeared (see #3357)"
    fi

    # --- Test 3: Permissions structure ---
    if [[ "$(jq 'has("permissions")' "$settings_file")" == "true" ]]; then
        allow_type=$(jq -r '.permissions.allow | type' "$settings_file" 2>/dev/null || echo missing)
        deny_type=$(jq -r '.permissions.deny | type' "$settings_file" 2>/dev/null || echo missing)
        allow_count=$(jq '.permissions.allow | length' "$settings_file" 2>/dev/null || echo 0)
        deny_count=$(jq '.permissions.deny | length' "$settings_file" 2>/dev/null || echo 0)
        if [[ "$allow_type" != array && "$allow_type" != null ]] || [[ "$deny_type" != array && "$deny_type" != null ]]; then
            fail "Permissions: allow/deny must be arrays (got allow=$allow_type deny=$deny_type)"
        elif (( allow_count + deny_count == 0 )); then
            fail "Permissions: present but empty — a block with no rules is a claim with no enforcement"
        else
            pass "Permissions: $allow_count allow, $deny_count deny rules"
        fi
    else
        fail "Permissions: absent — it is the only key this file still exists to carry"
    fi
done

# --- Summary ---
echo ""
echo "========================================"
echo -e "  Total: $((TOTAL_PASSED + TOTAL_FAILED))  |  Passed: ${GREEN}${TOTAL_PASSED}${NC}  |  Failed: ${RED}${TOTAL_FAILED}${NC}"
echo "========================================"

if [[ "$TOTAL_FAILED" -gt 0 ]]; then
    exit 1
fi
